SELECT "Name of ICI"
FROM clinical_trials
WHERE "Cancer type" = 'Small Cell Lung';

SELECT "Originial publication or Follow-up"
FROM clinical_trials
WHERE "Cancer type" = 'Esophageal/GEJ';

SELECT "Type of therapy"
FROM clinical_trials
WHERE "Cancer type" = 'Prostate';

SELECT "Trial name"
FROM clinical_trials
WHERE "Name of ICI" = 'Avelumab' AND "Cancer type" = 'Multiple Myeloma';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'NSCLC' AND "Type of combination" = 'ICI+TKI';
